document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',e=>{const t=document.querySelector(a.getAttribute('href'));if(t){e.preventDefault();t.scrollIntoView({behavior:'smooth'});document.querySelector('nav').classList.remove('open');document.querySelector('.menu').setAttribute('aria-expanded','false')}}));
const menu=document.querySelector('.menu');menu.setAttribute('aria-expanded','false');menu.addEventListener('click',()=>menu.setAttribute('aria-expanded',String(document.querySelector('nav').classList.toggle('open'))));
const booking=document.createElement('dialog');booking.id='booking';booking.innerHTML='<button class="close" aria-label="关闭">×</button><section class="booking-form"><p class="section-tag">MEET YOUR VOLTERRA</p><h2>预约试驾体验</h2><p>选择车型与城市，保存本次体验意向。</p><form><label>车型<select name="model"><option>V1 · 都市轿跑</option><option>V7 · 全能 SUV</option></select></label><label>城市<select name="city" required><option value="">请选择城市</option><option>上海</option><option>北京</option><option>深圳</option><option>杭州</option><option>成都</option><option>其他城市</option></select></label><label>称呼<input name="name" required maxlength="30" autocomplete="name" placeholder="请输入称呼"></label><label>手机号码<input name="phone" required type="tel" pattern="1[3-9][0-9]{9}" maxlength="11" autocomplete="tel" placeholder="11位中国大陆手机号"></label><label class="consent"><input type="checkbox" required>我了解这是演示流程，信息仅用于当前页面展示，不会发送至服务器。</label><button class="button dark submit" type="submit">保存体验意向</button></form><p class="booking-note">暂无真实试驾服务，不产生门店预约或电话联系。</p></section><section class="booking-success" hidden><span class="success-symbol">✓</span><h2>体验意向已记录</h2><p class="summary"></p><p>本次为演示体验，尚未提交至门店。关闭后您的信息将清除。</p><button class="button dark finish">完成</button></section>';document.body.append(booking);
let opener;document.querySelectorAll('.nav-cta,.contact .button').forEach(a=>{a.href='#contact';a.addEventListener('click',e=>{e.preventDefault();opener=a;booking.showModal()})});
const form=booking.querySelector('form');booking.querySelector('.close').onclick=()=>booking.close();booking.querySelector('.finish').onclick=()=>booking.close();booking.addEventListener('close',()=>{form.reset();booking.querySelector('.booking-form').hidden=false;booking.querySelector('.booking-success').hidden=true;booking.querySelector('.summary').textContent='';opener?.focus()});form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);if(!String(data.get('name')).trim()){form.elements.name.setCustomValidity('请输入有效称呼');form.elements.name.reportValidity();return}booking.querySelector('.summary').textContent=String(data.get('name')).trim()+'，您的意向：'+data.get('model')+' · '+data.get('city');booking.querySelector('.booking-form').hidden=true;booking.querySelector('.booking-success').hidden=false;booking.querySelector('.finish').focus()});form.elements.name.oninput=()=>form.elements.name.setCustomValidity('');
document.querySelector('.hero-meta').insertAdjacentHTML('afterend','<p class="concept-note">原创品牌与车型概念 · 参数为设计目标，非量产承诺</p>');document.querySelector('footer').children[1].textContent='© 2026 VOLTERRA 沃途 · 原创品牌展示';document.querySelector('footer').children[2].textContent='设计演示 · 暂无实际销售与试驾服务';document.querySelector('.line-link').textContent='探索品牌体验';
document.querySelector('.card-image.two').style.backgroundImage="url('assets/hero.png')";document.querySelector('.card-image.two').style.backgroundPosition='80% center';document.querySelector('.card-image.two').style.filter='grayscale(.55)';document.querySelectorAll('.card-image').forEach(a=>a.setAttribute('role','img'));document.querySelectorAll('.card-image').forEach(a=>a.setAttribute('aria-label','沃途品牌概念汽车展示，非量产车型实拍'));
document.querySelectorAll('.card').forEach((card,i)=>{const button=document.createElement('button');button.className='model-experience';button.textContent='体验这款车';button.onclick=()=>{opener=button;form.elements.model.selectedIndex=i;booking.showModal()};card.append(button)});
